const JP_DANCE_HD = {"teto_gotica":"data:image/png;base64,","miku_neon":"data:image/png;base64,","miku_maid":"data:image/png;base64,"};

const JP_DANCE_IMAGES = new Map();

function jpDanceHDFrame(id, frame, x, y) {
  const key = jpGuestShow.wardrobe[id];
  if (!JP_DANCE_HD[key]) return false;
  let image = JP_DANCE_IMAGES.get(key);
  if (!image) {
    image = new Image();
    JP_DANCE_IMAGES.set(key, image);
    image.src = JP_DANCE_HD[key];
  }
  if (!image.complete || !image.naturalWidth) return false;
  ctx.drawImage(image, frame * 126, 0, 126, 120, x - 21, y - 36, 42, 40);
  return true;
}
